/**
 * Automated Verification: Dynamic Store Profile & Receipt Customization on Thermal Slips
 * Tests that customized store details (Name, Phone, Address, Tax/BRN, Currency, Width, Footer, Logo)
 * immediately and dynamically appear on every thermal slip generated by:
 * 1. app.js (receiptHTML)
 * 2. print-system.js (ReceiptTemplateEngine.generateHtml & toCanonical)
 * 3. pdf-invoice.js (getThermalSlipBodyHTML & getThermalSlipHTML)
 */

const assert = require('assert');
const fs = require('fs');
const vm = require('vm');

const { ReceiptTemplateEngine } = require('./print-system.js');
const PDFInvoice = require('./pdf-invoice.js');

console.log('🧪 Starting Thermal Invoice Dynamic Store Customization Test Suite...\n');

let passedTests = 0;
function test(name, fn) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passedTests++;
  } catch (err) {
    console.error(`  ✗ ${name}`);
    console.error('    Error:', err.message);
    process.exitCode = 1;
  }
}

// Prepare app.js sandbox with DOM mocks
function createAppContext(customShop) {
  const makeEl = (init = {}) => Object.assign({
    textContent: '',
    value: '',
    innerHTML: '',
    style: {},
    className: '',
    classList: { add: () => {}, remove: () => {}, toggle: () => {}, contains: () => false },
    addEventListener: () => {},
    removeEventListener: () => {},
    setAttribute: () => {},
    getAttribute: () => null,
    focus: () => {},
    click: () => {}
  }, init);

  const domElements = {
    receipt: makeEl({ className: '', innerHTML: '' }),
    shopName: makeEl({ value: customShop.name }),
    shopPhone: makeEl({ value: customShop.phone }),
    shopAddress: makeEl({ value: customShop.address }),
    shopReg: makeEl({ value: customShop.regNo }),
    shopCurrency: makeEl({ value: customShop.currency }),
    receiptWidth: makeEl({ value: customShop.receiptWidth }),
    shopFooter: makeEl({ value: customShop.receiptFooter }),
    allowNegativeStockCheckbox: makeEl({ checked: false }),
    saveShop: makeEl({ onclick: null }),
    headerShopTitle: makeEl(),
    headerShopSubtitle: makeEl(),
    headerShopLogo: makeEl({ src: '' }),
    shopLogoPreview: makeEl({ src: '' })
  };

  const sandbox = {
    document: {
      addEventListener: () => {},
      getElementById: (id) => {
        if (!domElements[id]) domElements[id] = makeEl();
        return domElements[id];
      },
      querySelector: () => null,
      querySelectorAll: () => [],
      createElement: () => makeEl({ width: 0, height: 0, getContext: () => ({ drawImage: () => {} }), toDataURL: () => '' }),
      body: makeEl({ appendChild: () => {} })
    },
    window: {
      addEventListener: () => {},
      print: () => {}
    },
    localStorage: {
      _store: {},
      getItem(k) { return this._store[k] || null; },
      setItem(k, v) { this._store[k] = String(v); },
      removeItem(k) { delete this._store[k]; }
    },
    navigator: {
      clipboard: { writeText: async () => {} }
    },
    crypto: {
      randomUUID: () => 'uuid-1234',
      subtle: { importKey: async () => ({}), verify: async () => true }
    },
    setTimeout: setTimeout,
    clearTimeout: clearTimeout,
    setInterval: setInterval,
    clearInterval: clearInterval,
    PDFInvoice: PDFInvoice,
    toast: () => {},
    alert: () => {},
    console: console,
    atob: (s) => Buffer.from(s, 'base64').toString('binary'),
    TextDecoder: TextDecoder,
    TextEncoder: TextEncoder
  };

  // Seed db with custom shop
  sandbox.localStorage.setItem('harsh_apex_pos_v1', JSON.stringify({
    products: [],
    sales: [],
    shop: Object.assign({}, customShop),
    categories: []
  }));

  const appCode = fs.readFileSync('app.js', 'utf8');
  // Skip the IIFE subscription gate for testing pure receipt/store logic
  const cleanedCode = appCode.replace(/\(async function subscriptionGate\(\)[\s\S]*?\)\(\);/, '// subscriptionGate bypassed');

  vm.createContext(sandbox);
  vm.runInContext(cleanedCode, sandbox);

  return sandbox;
}

const customShop = {
  name: 'Silva Super Center',
  phone: '077 999 8888',
  address: 'Kandy Road, Kiribathgoda',
  regNo: 'VAT-998877',
  currency: 'LKR',
  receiptWidth: '80mm',
  receiptFooter: 'Goods once sold cannot be returned without bill.',
  logo: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg=='
};

const sampleSale = {
  id: 'SLV-2026-9081',
  number: 'SLV-2026-9081',
  at: '2026-10-26T10:30:00Z',
  method: 'Cash',
  items: [
    { name: 'Keells Samba Rice 5kg', qty: 1, unit: 'pcs', price: 1250, lineTotal: 1250 },
    { name: 'Red Dhal Mysore', qty: 1.5, unit: 'kg', price: 380, lineTotal: 570 }
  ],
  subtotal: 1820,
  discount: 70,
  total: 1750,
  received: 2000,
  change: 250
};

// -------------------------------------------------------------
// 1. app.js: receiptHTML & money() custom store details
// -------------------------------------------------------------
test('app.js receiptHTML: Immediately reflects customized store details and currency', () => {
  const ctx = createAppContext(customShop);
  const html = ctx.receiptHTML(sampleSale);

  assert(html.includes('Silva Super Center'), 'Store name missing');
  assert(html.includes('Kandy Road, Kiribathgoda'), 'Store address missing');
  assert(html.includes('Tel: 077 999 8888'), 'Phone missing or improperly formatted');
  assert(html.includes('Tax / BRN: VAT-998877'), 'Tax / BRN missing or improperly formatted');
  assert(html.includes('LKR 1,750.00'), 'Dynamic currency symbol LKR missing in grand total');
  assert(html.includes('LKR 1,820.00'), 'Dynamic currency symbol LKR missing in subtotal');
  assert(html.includes('LKR 1,250.00'), 'Dynamic currency symbol LKR missing in item total');
  assert(html.includes('Goods once sold cannot be returned without bill.'), 'Custom footer message missing');
  assert(html.includes('Powered by Harsh Apex Digital'), 'Branding line missing');
  assert(html.includes('data:image/png;base64'), 'Custom logo missing');
});

// -------------------------------------------------------------
// 2. app.js: Settings saveShop & updateShopDisplay persistence
// -------------------------------------------------------------
test('app.js saveShop: Permanently saves new store details to db.shop and PDFInvoice config', () => {
  const ctx = createAppContext({
    name: 'Initial Name',
    phone: '',
    address: '',
    regNo: '',
    currency: 'Rs.',
    receiptWidth: '58mm',
    receiptFooter: ''
  });

  // Business owner modifies fields in Settings UI
  ctx.document.getElementById('shopName').value = 'Apex Mega Mart Express';
  ctx.document.getElementById('shopPhone').value = '011 2345678 / 077 7654321';
  ctx.document.getElementById('shopAddress').value = '100 Galle Road, Colombo 03';
  ctx.document.getElementById('shopReg').value = 'BR-882299';
  ctx.document.getElementById('shopCurrency').value = 'EUR';
  ctx.document.getElementById('receiptWidth').value = '80mm';
  ctx.document.getElementById('shopFooter').value = 'Thank you! No returns after 7 days.';

  // Trigger Save Store Details
  ctx.document.getElementById('saveShop').onclick();

  // Verify updated in memory and localStorage
  const currentDb = vm.runInContext('db', ctx);
  assert.strictEqual(currentDb.shop.name, 'Apex Mega Mart Express');
  assert.strictEqual(currentDb.shop.phone, '011 2345678 / 077 7654321');
  assert.strictEqual(currentDb.shop.address, '100 Galle Road, Colombo 03');
  assert.strictEqual(currentDb.shop.regNo, 'BR-882299');
  assert.strictEqual(currentDb.shop.currency, 'EUR');
  assert.strictEqual(currentDb.shop.receiptWidth, '80mm');
  assert.strictEqual(currentDb.shop.receiptFooter, 'Thank you! No returns after 7 days.');

  const savedInStorage = JSON.parse(ctx.localStorage.getItem('harsh_apex_pos_v1'));
  assert.strictEqual(savedInStorage.shop.name, 'Apex Mega Mart Express');
  assert.strictEqual(savedInStorage.shop.currency, 'EUR');

  // Verify thermal slip instantly uses EUR and updated name
  const updatedHtml = ctx.receiptHTML(sampleSale);
  assert(updatedHtml.includes('Apex Mega Mart Express'));
  assert(updatedHtml.includes('EUR 1,750.00'));
  assert(updatedHtml.includes('Tax / BRN: BR-882299'));
  assert(updatedHtml.includes('Thank you! No returns after 7 days.'));
});

// -------------------------------------------------------------
// 3. print-system.js: ReceiptTemplateEngine generateHtml
// -------------------------------------------------------------
test('print-system.js: generateHtml embeds dynamic store customization and currency', () => {
  const canonical = ReceiptTemplateEngine.toCanonical(sampleSale, customShop);
  assert.strictEqual(canonical.store.name, 'Silva Super Center');
  assert.strictEqual(canonical.store.phone, '077 999 8888');
  assert.strictEqual(canonical.store.regNo, 'VAT-998877');
  assert.strictEqual(canonical.store.currency, 'LKR');
  assert.strictEqual(canonical.store.receiptWidth, '80mm');
  assert.strictEqual(canonical.store.footer, 'Goods once sold cannot be returned without bill.');

  const html = ReceiptTemplateEngine.generateHtml(canonical);
  assert(html.includes('receipt-80'), 'Must apply receipt-80 CSS class when 80mm');
  assert(html.includes('Silva Super Center'), 'Store name missing');
  assert(html.includes('Kandy Road, Kiribathgoda'), 'Address missing');
  assert(html.includes('Tel: 077 999 8888'), 'Phone missing');
  assert(html.includes('Tax / BRN: VAT-998877'), 'Tax / BRN missing');
  assert(html.includes('LKR 1,750.00'), 'Dynamic currency missing from Grand Total');
  assert(html.includes('LKR 1,820.00'), 'Dynamic currency missing from Subtotal');
  assert(html.includes('Goods once sold cannot be returned without bill.'), 'Footer missing');
  assert(html.includes('Powered by Harsh Apex Digital'), 'Branding line missing');
});

// -------------------------------------------------------------
// 4. pdf-invoice.js: getThermalSlipBodyHTML & getThermalSlipHTML
// -------------------------------------------------------------
test('pdf-invoice.js: getThermalSlipBodyHTML dynamically formats custom store profile', () => {
  const slipBody = PDFInvoice.getThermalSlipBodyHTML(sampleSale, customShop);
  assert(slipBody.includes('slip-80'), 'Must apply slip-80 class for 80mm setting');
  assert(slipBody.includes('Silva Super Center'), 'Store name missing');
  assert(slipBody.includes('Kandy Road, Kiribathgoda'), 'Store address missing');
  assert(slipBody.includes('Tel: 077 999 8888'), 'Phone missing');
  assert(slipBody.includes('Tax / BRN: VAT-998877'), 'Tax / BRN missing');
  assert(slipBody.includes('LKR 1,750.00'), 'Dynamic currency missing from Grand Total');
  assert(slipBody.includes('Goods once sold cannot be returned without bill.'), 'Footer message missing');
  assert(slipBody.includes('Powered by Harsh Apex Digital'), 'Branding line missing');

  const fullDoc = PDFInvoice.getThermalSlipHTML(sampleSale, customShop);
  assert(fullDoc.includes('width: 80mm'), 'getThermalSlipHTML CSS must adopt 80mm from custom shop');
  assert(fullDoc.includes('Silva Super Center'));
});

// -------------------------------------------------------------
// 5. Fallback behavior when optional fields are empty
// -------------------------------------------------------------
test('Graceful fallback when store fields are omitted or blank', () => {
  const minimalShop = {
    name: '',
    phone: '',
    address: '',
    regNo: '',
    currency: '',
    receiptWidth: '',
    receiptFooter: ''
  };

  const canonical = ReceiptTemplateEngine.toCanonical(sampleSale, minimalShop);
  assert.strictEqual(canonical.store.name, 'Harsh Apex Retail POS');
  assert.strictEqual(canonical.store.currency, 'Rs.');
  assert.strictEqual(canonical.store.receiptWidth, '58mm');

  const html = ReceiptTemplateEngine.generateHtml(canonical);
  assert(html.includes('receipt-58'));
  assert(html.includes('Harsh Apex Retail POS'));
  assert(html.includes('Rs. 1,750.00'));
  // Ensure no broken tags for missing optional fields
  assert(!html.includes('Tax / BRN: </p>'));
  assert(!html.includes('Tel: </p>'));
});

console.log('\n======================================================');
console.log(`🎉 Thermal Invoice Customization Suite: ${passedTests} passed`);
console.log('======================================================\n');
